WITH target_routes AS ( /* Optimization 1: Moving massive IN clause to a CTE to prevent internal engine errors */ SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (122, 123), (123, 122), (123, 141), (124, 122), (122, 124), (124, 134), (122, 71756), (757, 733), (71756, 122), (130, 624), (74820, 74694), (624, 130), (74694, 74820), (130, 309), (122, 216), (124, 123), (134, 122), (130, 575), (124, 462), (123, 124), (462, 124), (122, 71929), (130, 641), (575, 130), (141, 126), (130, 1476), (233, 123), (74661, 122), (641, 130), (248, 134), (126, 141), (122, 995), (130, 361), (995, 122), (71425, 122), (309, 462), (361, 130), (1476, 130), (65976, 130), (122, 95218), (551, 473), (130, 95083), (130, 311), (141, 71929), (624, 124), (313, 551), (95218, 122), (1514, 733), (74701, 79589), (71929, 141), (1290, 733), (123, 504), (122, 78796), (470, 1169), (123, 506), (1382, 130), (733, 1290), (71756, 123), (1437, 733), (624, 361), (70015, 777), (130, 1384), (74701, 93059), (313, 94152), (733, 1437), (361, 624), (70024, 83760), (1384, 130), (122, 923), (130, 65907), (309, 575), (93947, 70014), (575, 309), (1443, 807), (807, 1290), (624, 444), (130, 65859), (833, 777), (646, 130), (1429, 1290), (130, 622), (70015, 833), (122, 65930), (1429, 777), (629, 130), (1290, 1429), (141, 124), (622, 130), (70015, 1290), (777, 1429) ) AS t(s, d) ), offer_tuple AS ( SELECT DISTINCT src_id, dest_id FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-27 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND country = 'IND' ), confirm_deduped AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', at_timezone(time_of_event, 'Asia/Kolkata')) AS DATE) AS doi, tin, user_type, order_uuid, source_location_id, destination_location_id FROM "transaction"."bus_ticket_events" WHERE time_of_event >= TIMESTAMP '2025-12-31 18:30:00' AND time_of_event < TIMESTAMP '2026-01-27 18:30:00' AND event_class = 2 AND event_type = 101 AND tin IS NOT NULL AND tin NOT IN ('', 'null') ), PaySys AS ( SELECT order_uuid, MAX(org_unit_amount) org_unit_amount FROM "transaction"."bus_payment_events" WHERE date_of_issue >= timestamp '2026-01-06 18:30:00' AND date_of_issue < timestamp '2026-01-27 18:30:00' AND payment_system_ref_no LIKE ('%DBIND%')AND country_code = 'IND' GROUP BY 1 ) SELECT CASE WHEN c.doi >= DATE '2026-01-01' AND c.doi < DATE '2026-01-07' THEN 'Pre DBS' WHEN c.doi > DATE '2026-01-07' AND c.doi < DATE '2026-01-28' THEN CAST(c.doi AS VARCHAR) ELSE 'Other Period' END AS doi, -- India COUNT(DISTINCT tin) india_overall_txn_count, COUNT(DISTINCT CASE WHEN UPPER(c.user_type) = 'NEW' THEN tin END) AS india_new_users_txn_count, -- DBS COUNT(DISTINCT CASE WHEN ot.src_id IS NOT NULL AND ot.dest_id IS NOT NULL THEN tin END) AS dbs_overall_txn_count, COUNT(DISTINCT CASE WHEN ot.src_id IS NOT NULL AND ot.dest_id IS NOT NULL AND UPPER(c.user_type) = 'NEW' THEN tin END) AS dbs_new_users_txn_count, -- Target COUNT(DISTINCT CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL THEN tin END) AS target_overall_txn_count, COUNT(DISTINCT CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL AND UPPER(c.user_type) = 'NEW' THEN tin END) AS target_new_users_txn_count, -- DBS Seats COUNT(DISTINCT CASE WHEN ot.src_id IS NOT NULL AND ot.dest_id IS NOT NULL AND ps.order_uuid IS NOT NULL THEN tin END) AS dbs_seats_txn_count, COUNT(DISTINCT CASE WHEN ot.src_id IS NOT NULL AND ot.dest_id IS NOT NULL AND ps.order_uuid IS NOT NULL AND UPPER(c.user_type) = 'NEW' THEN tin END) AS dbs_seats_new_users_txn_count, -- Target Seats COUNT(DISTINCT CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL AND ps.order_uuid IS NOT NULL THEN tin END) AS target_seats_overall_txn_count, COUNT(DISTINCT CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL AND ps.order_uuid IS NOT NULL AND UPPER(c.user_type) = 'NEW' THEN tin END) AS target_seats_new_users_txn_count FROM confirm_deduped c LEFT JOIN PaySys ps ON ps.order_uuid = c.order_uuid LEFT JOIN offer_tuple ot ON c.source_location_id = ot.src_id AND c.destination_location_id = ot.dest_id LEFT JOIN target_routes tr ON c.source_location_id = tr.src_id AND c.destination_location_id = tr.dest_id GROUP BY 1 ORDER BY 1
